-- Formulas
INSERT OR IGNORE INTO formulas (id, subject_id, slug, name, latex, description, variables, status) VALUES ('frm_3ede8298de7e4e', 'subj_math', 'taylor-series', 'Taylor series', 'f(x) = \sum_{n=0}^{\infty} \frac{f^{(n)}(a)}{n!}(x - a)^n = f(a) + f''(a)(x - a) + \frac{f''''(a)}{2!}(x - a)^2 + \cdots', 'The Taylor series of f about x = a (a Maclaurin series when a = 0), valid where the series converges to f.', '[{"symbol":"a","meaning":"center"},{"symbol":"f^{(n)}(a)","meaning":"nth derivative at the center"}]', 'published');
INSERT OR IGNORE INTO formulas (id, subject_id, slug, name, latex, description, variables, status) VALUES ('frm_b15d0d882811b3', 'subj_math', 'series-error-bounds', 'Series error bounds', '|R_n(x)| \le \frac{\max|f^{(n+1)}|}{(n + 1)!}|x - a|^{n+1}, \qquad |S - S_n| \le a_{n+1}\ \text{(alternating)}', 'Lagrange error bound for a degree-n Taylor polynomial, and the alternating series error bound (for alternating series whose terms decrease to 0).', '[{"symbol":"R_n","meaning":"remainder f − Pₙ"},{"symbol":"a_{n+1}","meaning":"first omitted term''s size"}]', 'published');

-- Lesson: absolute-conditional-convergence
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_e4d9f2078b16ab', 'absolute-conditional-convergence', 'Determining absolute or conditional convergence', 'Classify convergent series as absolutely convergent (Σ|aₙ| converges) or conditionally convergent, and know that absolute convergence implies convergence.', 25, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_331ff24f5b317c', 'les_e4d9f2078b16ab', 1, 'Test Σ|aₙ| first; if it converges, Σaₙ converges absolutely.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_6a802eb3722be4', 'les_e4d9f2078b16ab', 2, 'If Σ|aₙ| diverges but Σaₙ converges, the convergence is conditional.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_a8a30e9def3308', 'les_e4d9f2078b16ab', 3, 'Choose tests in a sensible order.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_331ff24f5b317c', 'les_e4d9f2078b16ab', 'learn', 1, 'definition', '{"term":"Definitions","body":"$\\sum a_n$ converges absolutely if $\\sum |a_n|$ converges; then $\\sum a_n$ also converges. It converges conditionally if $\\sum a_n$ converges but $\\sum |a_n|$ diverges."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_6a802eb3722be4', 'les_e4d9f2078b16ab', 'learn', 2, 'worked_example', '{"title":"Classify three series","steps":[{"latex":"\\sum \\frac{(-1)^n}{n^2}:\\ \\sum \\frac{1}{n^2} \\text{ converges}","explanation":"Absolutely convergent."},{"latex":"\\sum \\frac{(-1)^n}{n}:\\ \\sum \\frac{1}{n} \\text{ diverges; AST converges}","explanation":"Conditionally convergent."},{"latex":"\\sum (-1)^n:\\ \\text{terms don''t} \\to 0","explanation":"Divergent."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_a8a30e9def3308', 'les_e4d9f2078b16ab', 'learn', 3, 'callout', '{"tone":"note","title":"Why it matters","body":"Rearranging the terms of an absolutely convergent series doesn''t change its sum. A conditionally convergent series can be rearranged to add up to any number you like (Riemann''s rearrangement theorem)."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_5200dffc2db4b6', 'les_e4d9f2078b16ab', 'learn', 4, 'callout', '{"tone":"application","title":"Where this shows up","body":"Numerical software prefers absolutely convergent series because adding terms in any order (or in parallel) gives the same answer."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_331ff24f5b317c', 'les_e4d9f2078b16ab', 1, 'practice', 'multiple_choice', 1, '$\sum \frac{(-1)^n}{3^n}$ is…', '{"choices":["absolutely convergent","conditionally convergent","divergent"],"answer":0}', '[]', '$\sum \frac{1}{3^n}$ converges.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_6a802eb3722be4', 'les_e4d9f2078b16ab', 2, 'practice', 'multiple_choice', 2, '$\sum \frac{(-1)^n}{\sqrt{n}}$ is…', '{"choices":["absolutely convergent","conditionally convergent","divergent"],"answer":1}', '[]', '$\sum \frac{1}{\sqrt{n}}$ diverges; the AST gives convergence.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_a8a30e9def3308', 'les_e4d9f2078b16ab', 3, 'practice', 'multiple_choice', 2, '$\sum \frac{\sin n}{n^2}$ is…', '{"choices":["absolutely convergent","conditionally convergent","divergent"],"answer":0}', '["$\\left|\\frac{\\sin n}{n^2}\\right| \\le \\frac{1}{n^2}$."]', 'Comparison on the absolute values.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_5200dffc2db4b6', 'les_e4d9f2078b16ab', 4, 'review', 'multiple_choice', 3, 'If $\sum |a_n|$ diverges, then $\sum a_n$…', '{"choices":["diverges","converges conditionally","could converge or diverge","converges absolutely"],"answer":2}', '[]', 'Compare $\sum \frac{(-1)^n}{n}$ and $\sum \frac{1}{n}$.');
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_2f55bd7b329594', 'subj_math', 'infinite-series', 'Infinite series', 'Sums of infinitely many terms, defined as limits of partial sums.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_e4d9f2078b16ab', (SELECT id FROM concepts WHERE slug = 'infinite-series'));

-- Lesson: alternating-error-bound
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_51a189b4ae6f96', 'alternating-error-bound', 'Alternating series error bound', 'Bound the error in approximating an alternating series by a partial sum: it is at most the size of the first omitted term.', 25, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_2123885c9e116f', 'les_51a189b4ae6f96', 1, 'State the alternating series error bound |S − Sₙ| ≤ bₙ₊₁.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_a942d469281ea5', 'les_51a189b4ae6f96', 2, 'Find how many terms guarantee a given accuracy.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_7bcc02932880a1', 'les_51a189b4ae6f96', 3, 'Tell whether Sₙ overestimates or underestimates S.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_2123885c9e116f', 'les_51a189b4ae6f96', 'learn', 1, 'definition', '{"term":"Error bound","body":"If $\\sum (-1)^{n+1}b_n$ satisfies the alternating series test, then $|S - S_n| \\le b_{n+1}$. The error has the same sign as the first omitted term."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_a942d469281ea5', 'les_51a189b4ae6f96', 'learn', 2, 'worked_example', '{"title":"Approximate $\\ln 2 = 1 - \\tfrac{1}{2} + \\tfrac{1}{3} - \\tfrac{1}{4} + \\cdots$ with $S_4$","steps":[{"latex":"S_4 = \\tfrac{7}{12} \\approx 0.583","explanation":""},{"latex":"|\\ln 2 - S_4| \\le b_5 = \\tfrac{1}{5} = 0.2","explanation":"Actual error ≈ 0.110."},{"latex":"\\text{first omitted term is } +\\tfrac{1}{5} \\Rightarrow S_4 \\text{ underestimates}","explanation":""}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_7bcc02932880a1', 'les_51a189b4ae6f96', 'learn', 3, 'worked_example', '{"title":"How many terms of $\\sum \\frac{(-1)^{n+1}}{n^2}$ guarantee error below 0.01?","steps":[{"latex":"b_{n+1} = \\frac{1}{(n + 1)^2} < 0.01 \\Rightarrow n + 1 > 10","explanation":""},{"latex":"n = 10 \\text{ terms}","explanation":""}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_96e64959d34f39', 'les_51a189b4ae6f96', 'experiment', 4, 'activity', '{"activity":"series","title":"Watch the error shrink","params":{"series":"alternating","n":8}}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_04c1c0e2d725ff', 'les_51a189b4ae6f96', 'learn', 5, 'callout', '{"tone":"application","title":"Where this shows up","body":"Calculators decide when to stop adding series terms with error bounds like this one, guaranteeing the digits they display are correct."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_2123885c9e116f', 'les_51a189b4ae6f96', 1, 'practice', 'numeric', 1, 'Bound the error of $S_3$ for $\sum \frac{(-1)^{n+1}}{n^2}$.', '{"answer":0.0625,"tolerance":0.0001}', '[]', '$b_4 = \frac{1}{16}$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_a942d469281ea5', 'les_51a189b4ae6f96', 2, 'practice', 'numeric', 2, 'How many terms of $\sum \frac{(-1)^{n+1}}{n}$ guarantee error at most 0.001?', '{"answer":999}', '["Need $\\frac{1}{n + 1} \\le 0.001$."]', '$n + 1 \ge 1000$, so 999 terms.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_7bcc02932880a1', 'les_51a189b4ae6f96', 3, 'practice', 'multiple_choice', 2, 'For $\sum \frac{(-1)^{n+1}}{n!}$, $S_3$ compared with the sum is…', '{"choices":["an overestimate","an underestimate","exact","can''t tell"],"answer":0}', '["The first omitted term is $-\\frac{1}{4!}$."]', 'A negative omitted term means $S_3$ is too high.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_96e64959d34f39', 'les_51a189b4ae6f96', 4, 'review', 'multiple_choice', 3, 'Why can''t you use this bound for $\sum \frac{1}{n^2}$?', '{"choices":["Its terms don''t approach 0","It isn''t alternating","It diverges","It''s geometric"],"answer":1}', '[]', 'Use an integral bound instead.');
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_2f55bd7b329594', 'subj_math', 'infinite-series', 'Infinite series', 'Sums of infinitely many terms, defined as limits of partial sums.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_51a189b4ae6f96', (SELECT id FROM concepts WHERE slug = 'infinite-series'));
