-- Lesson: alternating-series-test
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_11829a4fd37d33', 'alternating-series-test', 'Alternating series test for convergence', 'Show that alternating series converge when their terms decrease in size to 0, and see why the partial sums zigzag toward the sum.', 25, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_3a8c6e2d71c6ef', 'les_11829a4fd37d33', 1, 'State the alternating series test and check both conditions.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_2c9bd5a4dc1dd3', 'les_11829a4fd37d33', 2, 'Explain the zigzag of partial sums.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_eff98da440a15d', 'les_11829a4fd37d33', 3, 'Recognize when the test doesn''t apply.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_3a8c6e2d71c6ef', 'les_11829a4fd37d33', 'learn', 1, 'definition', '{"term":"Alternating series test","body":"$\\sum (-1)^{n+1}b_n$ with $b_n > 0$ converges if (1) $b_{n+1} \\le b_n$ (eventually decreasing) and (2) $\\lim b_n = 0$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_2c9bd5a4dc1dd3', 'les_11829a4fd37d33', 'learn', 2, 'worked_example', '{"title":"Alternating harmonic series $1 - \\tfrac{1}{2} + \\tfrac{1}{3} - \\tfrac{1}{4} + \\cdots$","steps":[{"latex":"b_n = \\tfrac{1}{n} \\text{ decreases and } \\to 0","explanation":""},{"latex":"\\text{converges (to } \\ln 2 \\approx 0.693)","explanation":"Even though Σ1/n diverges."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_eff98da440a15d', 'les_11829a4fd37d33', 'experiment', 3, 'activity', '{"activity":"series","title":"Zigzagging partial sums","params":{"series":"alternating","n":20}}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_f686fab13188eb', 'les_11829a4fd37d33', 'experiment', 4, 'callout', '{"tone":"tip","title":"Try this","body":"Each partial sum overshoots, then undershoots, the green line by less each time. The sum is always trapped between consecutive partial sums."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_2691f33025fae1', 'les_11829a4fd37d33', 'learn', 5, 'callout', '{"tone":"warning","title":"Check both conditions","body":"$\\sum (-1)^n \\frac{n}{n + 1}$ alternates, but $b_n \\to 1$, so it diverges (nth term test)."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_f8c22736eaf8b1', 'les_11829a4fd37d33', 'learn', 6, 'callout', '{"tone":"application","title":"Where this shows up","body":"Many series for π and logarithms alternate; their slow zigzag explains why some of them need thousands of terms for a few digits."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_3a8c6e2d71c6ef', 'les_11829a4fd37d33', 1, 'practice', 'multiple_choice', 1, '$\sum (-1)^{n} \frac{1}{\sqrt{n}}$…', '{"choices":["converges by the alternating series test","diverges","diverges by the nth term test","is not alternating"],"answer":0}', '[]', '$\frac{1}{\sqrt{n}}$ decreases to 0.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_2c9bd5a4dc1dd3', 'les_11829a4fd37d33', 2, 'practice', 'multiple_choice', 2, '$\sum (-1)^n \frac{n^2}{n^2 + 1}$…', '{"choices":["converges","diverges"],"answer":1}', '[]', 'Terms don''t approach 0.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_eff98da440a15d', 'les_11829a4fd37d33', 3, 'practice', 'multiple_choice', 2, 'Which condition might fail for $b_n = \frac{2 + (-1)^n}{n}$?', '{"choices":["b_n > 0","b_n → 0","b_n decreasing","None"],"answer":2}', '[]', '$b_n$ goes $\frac{1}{1}, \frac{3}{2}, \frac{1}{3}, \frac{3}{4}, \ldots$: not decreasing.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_f686fab13188eb', 'les_11829a4fd37d33', 4, 'review', 'multiple_choice', 3, 'If an alternating series satisfies the test, its sum $S$ lies…', '{"choices":["above every partial sum","between any two consecutive partial sums","below every partial sum","at S₁"],"answer":1}', '[]', 'The partial sums alternate around $S$.');
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_2f55bd7b329594', 'subj_math', 'infinite-series', 'Infinite series', 'Sums of infinitely many terms, defined as limits of partial sums.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_11829a4fd37d33', (SELECT id FROM concepts WHERE slug = 'infinite-series'));

-- Lesson: comparison-tests
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_32205c1111ea07', 'comparison-tests', 'Comparison tests for convergence', 'Decide convergence of positive-term series by comparing them with known series, using the direct comparison and limit comparison tests.', 30, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_1b33878c304498', 'les_32205c1111ea07', 1, 'Apply the direct comparison test with an inequality in the right direction.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_bb1bd57c42d53b', 'les_32205c1111ea07', 2, 'Apply the limit comparison test with a well-chosen benchmark.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_c85ab981ed4df4', 'les_32205c1111ea07', 3, 'Choose benchmarks from geometric and p-series by dominant terms.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_1b33878c304498', 'les_32205c1111ea07', 'learn', 1, 'definition', '{"term":"Direct comparison","body":"For $0 \\le a_n \\le b_n$: if $\\sum b_n$ converges, so does $\\sum a_n$; if $\\sum a_n$ diverges, so does $\\sum b_n$. (Smaller than convergent converges; bigger than divergent diverges.)"}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_bb1bd57c42d53b', 'les_32205c1111ea07', 'learn', 2, 'definition', '{"term":"Limit comparison","body":"For $a_n, b_n > 0$, if $\\lim \\frac{a_n}{b_n} = L$ with $0 < L < \\infty$, then both series converge or both diverge."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_c85ab981ed4df4', 'les_32205c1111ea07', 'learn', 3, 'worked_example', '{"title":"$\\sum \\dfrac{1}{n^2 + 5}$","steps":[{"latex":"\\frac{1}{n^2 + 5} < \\frac{1}{n^2}","explanation":""},{"latex":"\\sum \\tfrac{1}{n^2} \\text{ converges} \\Rightarrow \\text{converges}","explanation":"Direct comparison."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_0d25664cabac37', 'les_32205c1111ea07', 'learn', 4, 'worked_example', '{"title":"$\\sum \\dfrac{3n + 1}{n^3 - 2}$","steps":[{"latex":"\\text{dominant terms: } \\tfrac{3n}{n^3} \\sim \\tfrac{1}{n^2}","explanation":"Choose b_n = 1/n²."},{"latex":"\\lim \\frac{(3n + 1)/(n^3 - 2)}{1/n^2} = 3","explanation":"Finite and positive."},{"latex":"\\text{converges}","explanation":"Limit comparison with a p-series, p = 2."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_bd333116a45746', 'les_32205c1111ea07', 'learn', 5, 'callout', '{"tone":"warning","title":"Inequalities that prove nothing","body":"Showing $\\frac{1}{n^2 - 5} > \\frac{1}{n^2}$ (bigger than a convergent series) proves nothing. Use limit comparison instead."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_ea906b4c51e721', 'les_32205c1111ea07', 'learn', 6, 'callout', '{"tone":"application","title":"Where this shows up","body":"Engineers bound complicated error sums by simpler geometric ones to guarantee that an algorithm''s total error stays finite."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_1b33878c304498', 'les_32205c1111ea07', 1, 'practice', 'multiple_choice', 1, '$\sum \frac{1}{2^n + 3}$ converges by comparison with…', '{"choices":["$\\sum \\frac{1}{n}$","$\\sum \\frac{1}{2^n}$","$\\sum \\frac{1}{3}$","$\\sum 2^n$"],"answer":1}', '[]', 'Smaller than a convergent geometric series.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_bb1bd57c42d53b', 'les_32205c1111ea07', 2, 'practice', 'multiple_choice', 2, '$\sum \frac{1}{\sqrt{n} - 0.5}$…', '{"choices":["converges","diverges"],"answer":1}', '["Compare with $\\frac{1}{\\sqrt{n}}$."]', 'Bigger than a divergent p-series ($p = \frac{1}{2}$).');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_c85ab981ed4df4', 'les_32205c1111ea07', 3, 'practice', 'multiple_choice', 2, 'For $\sum \frac{n^2 + 1}{n^4 + n}$, the best benchmark is…', '{"choices":["$\\frac{1}{n}$","$\\frac{1}{n^2}$","$\\frac{1}{n^4}$","$\\frac{1}{2^n}$"],"answer":1}', '[]', 'Dominant terms $\frac{n^2}{n^4}$. The series converges.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_0d25664cabac37', 'les_32205c1111ea07', 4, 'review', 'multiple_choice', 3, 'Limit comparison gives $L = 0$ with a divergent $\sum b_n$. Conclusion?', '{"choices":["Converges","Diverges","Inconclusive","Sum is 0"],"answer":2}', '[]', 'The test needs $0 < L < \infty$.');
